const allMessages = $input.all().map(item => item.json);

const sortedMessages = [...allMessages].sort((a, b) =>
  new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
);

const historyMessages = [...sortedMessages].reverse();
const historyLines = historyMessages.map(msg => {
  const isBot = msg.author?.bot === true;
  const name = isBot ? 'StorSprut' : (msg.author?.global_name || msg.author?.username || 'Användare');
  const content = msg.content.replace(/<@\d+>/g, '').trim();
  return `${name}: ${content}`;
}).filter(line => !line.endsWith(': '));

const conversationHistory = historyLines.join('\n');

const botId = '1467458709025329272';
const newItems = [];

for (let i = 0; i < sortedMessages.length; i++) {
  const msg = sortedMessages[i];
  if (msg.author?.bot === true) continue;
  if (!msg.content.includes(`<@${botId}>`)) continue;
  const msgTime = new Date(msg.timestamp).getTime();
  if (Date.now() - msgTime > 120000) continue;

  let hasReply = false;
  for (let j = 0; j < i; j++) {
    if (sortedMessages[j].author?.bot === true) {
      hasReply = true;
      break;
    }
  }
  if (hasReply) continue;

  const cleanContent = msg.content.replace(/<@\d+>/g, '').trim();
  newItems.push({
    json: {
      messageId: msg.id,
      channelId: msg.channel_id,
      authorName: msg.author?.global_name || msg.author?.username,
      cleanContent: cleanContent,
      conversationHistory: conversationHistory
    }
  });
  break;
}

return newItems;

const question = $json.cleanContent;

const keywords = {
  materials: ['lager', 'skum', 'material', 'stock', 'hur mycket har vi'],
  bookings: ['bokning', 'bokat', 'schema', 'installation', 'nästa vecka', 'schemat', 'bokningar'],
  tasks: ['uppgift', 'att göra', 'todo', 'uppgifter'],
  quotes: ['offert', 'offerter'],
  search: ['hitta', 'sök', 'vem', 'berätta om'],
  dashboard: ['idag', 'översikt', 'dashboard', 'hur ser det ut']
};

const q = question.toLowerCase();
let endpoint = 'dashboard';
let searchQuery = '';

for (const [ep, words] of Object.entries(keywords)) {
  if (words.some(w => q.includes(w))) {
    endpoint = ep;
    break;
  }
}

if (endpoint === 'search') {
  searchQuery = question.replace(/hitta|sök efter|sök|berätta om|vem är/gi, '').trim();
}

const base = 'https://www.intellifoam.se/api/integrations/bot';
const params = [];
if (searchQuery) params.push('q=' + encodeURIComponent(searchQuery));

let url = base + '/' + endpoint;
if (params.length > 0) url += '?' + params.join('&');

try {
  const data = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: { 'x-api-key': 'intellifoam_n8n_2026' },
    json: true
  });
  return { json: { question, endpoint, data: JSON.stringify(data) } };
} catch(e) {
  return { json: { question, endpoint, data: '{"error":"' + e.message + '"}' } };
}

